    }

    /** +1 к десятичной строке без точки (внутр. помощник для HALF_UP). */
    private static function incrementDecimalString(string $s): string
    {
        // $s — десятичная строка без знака и без точки. Возвращает ($s + 1)
        // в строковом виде. Пример: "262498" -> "262499", "999999" -> "1000000".
        $out = '';
        $carry = 1;
        $len = strlen($s);
        for ($i = $len - 1; $i >= 0; $i--) {
            $sum = (int) $s[$i] + $carry;
            $carry = intdiv($sum, 10);
            $out .= (string) ($sum % 10);
            if ($carry === 0) {
                // перенос исчерпан — копируем оставшиеся цифе (старшие разряды) как есть
                break;
            }
        }
        if ($carry > 0) {
            $out .= '1';
        }
        // добавляем старшие разряды, которые не участвовали в переносе
        // (если цикл не дошёл до $i = 0)
        if ($carry === 0 && $i > 0) {
            $out .= substr($s, 0, $i);
        }

        return strrev($out);
    }
}

