private function fetchLastRatingsFor(array $eventIds): array
{
    if ($eventIds === []) {
        return [];
    }
    // берём max id по каждому event
    $rows = $this->em->getRepository(UsageRating::class)->createQueryBuilder('r')
        ->select('MAX(r.id) as mid, r.event as ev')
        ->groupBy('r.event')
        ->getQuery()
        ->getArrayResult();
    $mapping = [];
    foreach ($rows as $row) {
        /** @var UsageEvent $ev */
        $ev = $row['ev'];
        $id = (int) $row['mid'];
        if (!$ev instanceof UsageEvent) {
            continue;
        }
        $mapping[$ev->id()] = $id;
    }
    $ids = array_values($mapping);
    if ($ids === []) {
        return [];
    }
    $ratings = $this->em->getRepository(UsageRating::class)->createQueryBuilder('r')
        ->select('r')
        ->where('r.id IN (:ids)')
        ->setParameter('ids', $ids)
        ->getQuery()
        ->getResult();
    $byId = [];
    foreach ($ratings as $r) {
        $byId[$r->id()] = $r;
    }
    $result = [];
    foreach ($mapping as $eventKey => $ratingId) {
        if (isset($byId[$ratingId])) {
            $result[(int) $eventKey] = $byId[$ratingId];
        }
    }
    return $result;
}

